CREATE TABLE accounts (
    id bigint PRIMARY KEY,
    balance numeric(12, 2) NOT NULL CHECK (balance >= 0)
);

BEGIN;
UPDATE accounts SET balance = balance - 250.00 WHERE id = 101;
UPDATE accounts SET balance = balance + 250.00 WHERE id = 202;
COMMIT;

CREATE TABLE order_items (
    order_id bigint,
    product_id bigint,
    unit_price_at_purchase numeric(12, 2) NOT NULL,
    PRIMARY KEY (order_id, product_id)
);

WITH monthly_revenue AS (
    SELECT tenant_id, SUM(total_amount) as rev
    FROM orders GROUP BY tenant_id
)
SELECT * FROM monthly_revenue WHERE rev > 1000;
